'Numerical check for Exercise 14.1.'

from __future__ import annotations

import math

import os

from pathlib import Path

import numpy as np

_cache = Path(__file__).resolve().parents[1] / '.mplcache'
_cache.mkdir(exist_ok=True)

os.environ.setdefault('MPLCONFIGDIR', str(_cache))

os.environ.setdefault('XDG_CACHE_HOME', str(_cache))

def exercise_141() -> None:
    mu = np.array([1.07, 1.02])
    sigma = np.array([[0.0274, 0.00104], [0.00104, 0.00308]])
    inv_sigma = np.linalg.inv(sigma)
    one = np.ones(2)
    c2 = mu @ inv_sigma @ mu
    c1 = -2.0 * mu @ inv_sigma @ one
    c0 = one @ inv_sigma @ one
    y_star = -c1 / (2.0 * c2)
    min_bound = math.sqrt(c0 - c1 * c1 / (4.0 * c2))
    print('Exercise 14.1')
    print('HJ polynomial coefficients c2, c1, c0:')
    print(f'{c2:.6f} {c1:.6f} {c0:.6f}')
    print(f'minimum at E(m)={y_star:.6f}, bound={min_bound:.6f}')
    for ybar in [0.9, 0.95, 0.99, 1.0, 1.02]:
        bound = math.sqrt((one - ybar * mu) @ inv_sigma @ (one - ybar * mu))
        print(f'HJ bound at E(m)={ybar:.2f}: {bound:.6f}')
    cons_growth = EPDATA[:, 3]
    for gamma in [0, 5, 10]:
        m = 0.99 * cons_growth ** (-gamma)
        print(f'gamma={gamma:2d}: mean(m)={m.mean():.6f}, std(m)={m.std(ddof=1):.6f}')
    if os.environ.get('RMT_WRITE_FIGURES') != '1':
        print('skipping figure regeneration; set RMT_WRITE_FIGURES=1 to rebuild it.')
        return
    try:
        import matplotlib.pyplot as plt
    except ImportError:
        print('matplotlib not installed; skipping figure.')
        return
    ygrid = np.linspace(0.9, 1.02, 300)
    bounds = [math.sqrt((one - y * mu) @ inv_sigma @ (one - y * mu)) for y in ygrid]
    fig, ax = plt.subplots(figsize=(5.0, 3.5))
    ax.plot(ygrid, bounds, color='black', linewidth=1.4, label='HJ bound')
    for gamma, marker in [(0, 'o'), (5, 's'), (10, '^')]:
        m = 0.99 * cons_growth ** (-gamma)
        ax.scatter(m.mean(), m.std(ddof=1), color='black', marker=marker, label=f'$\\gamma={gamma}$')
    ax.set_xlabel('$E(m)$')
    ax.set_ylabel('$\\operatorname{std}(m)$')
    ax.legend(frameon=False, fontsize=8)
    ax.grid(True, color='0.85', linewidth=0.5)
    fig.tight_layout()
    out = Path(__file__).resolve().parents[1] / 'figures' / 'ch14_hj_bound.pdf'
    fig.savefig(out)
    plt.close(fig)
    print(f'wrote {out}')

